-- схема Catalog (6 таблиць) у PostgreSQL

CREATE SCHEMA IF NOT EXISTS "Catalog";

DROP TABLE IF EXISTS "Catalog"."ProductStores", "Catalog"."ProductImages",
    "Catalog"."ProductTags", "Catalog"."ProductAttributes",
    "Catalog"."Products", "Catalog"."Stores" CASCADE;

CREATE TABLE "Catalog"."Stores" (
    "Id"   integer NOT NULL,
    "Name" varchar(100) NOT NULL,
    "City" varchar(100) NOT NULL,
    CONSTRAINT "PK_Catalog_Stores" PRIMARY KEY ("Id")
);

CREATE TABLE "Catalog"."Products" (
    "Id"          integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Sku"         varchar(20)  NOT NULL,
    "Name"        varchar(200) NOT NULL,
    "Brand"       varchar(100) NOT NULL,
    "Category"    varchar(30)  NOT NULL,
    "RatingAvg"   numeric(2,1) NOT NULL,
    "RatingCount" integer      NOT NULL DEFAULT 0,
    "CreatedAt"   timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT "PK_Catalog_Products" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Catalog_Products_Sku" UNIQUE ("Sku")
);

CREATE TABLE "Catalog"."ProductAttributes" (
    "ProductId"   integer     NOT NULL,
    "Name"        varchar(50) NOT NULL,
    "ValueText"   varchar(200),
    "ValueNumber" numeric(12,2),
    CONSTRAINT "PK_Catalog_ProductAttributes" PRIMARY KEY ("ProductId", "Name"),
    CONSTRAINT "CK_Catalog_ProductAttributes_Value"
        CHECK (num_nonnulls("ValueText", "ValueNumber") = 1),
    CONSTRAINT "FK_Catalog_ProductAttributes_Products" FOREIGN KEY ("ProductId")
        REFERENCES "Catalog"."Products" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Catalog"."ProductTags" (
    "ProductId" integer     NOT NULL,
    "Tag"       varchar(50) NOT NULL,
    CONSTRAINT "PK_Catalog_ProductTags" PRIMARY KEY ("ProductId", "Tag"),
    CONSTRAINT "FK_Catalog_ProductTags_Products" FOREIGN KEY ("ProductId")
        REFERENCES "Catalog"."Products" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Catalog"."ProductImages" (
    "ProductId" integer      NOT NULL,
    "SortOrder" smallint     NOT NULL,
    "Url"       varchar(300) NOT NULL,
    CONSTRAINT "PK_Catalog_ProductImages" PRIMARY KEY ("ProductId", "SortOrder"),
    CONSTRAINT "FK_Catalog_ProductImages_Products" FOREIGN KEY ("ProductId")
        REFERENCES "Catalog"."Products" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Catalog"."ProductStores" (
    "ProductId" integer       NOT NULL,
    "StoreId"   integer       NOT NULL,
    "Price"     numeric(18,2) NOT NULL,
    "Stock"     integer       NOT NULL,
    CONSTRAINT "PK_Catalog_ProductStores" PRIMARY KEY ("ProductId", "StoreId"),
    CONSTRAINT "CK_Catalog_ProductStores_Price" CHECK ("Price" > 0),
    CONSTRAINT "CK_Catalog_ProductStores_Stock" CHECK ("Stock" >= 0),
    CONSTRAINT "FK_Catalog_ProductStores_Products" FOREIGN KEY ("ProductId")
        REFERENCES "Catalog"."Products" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Catalog_ProductStores_Stores" FOREIGN KEY ("StoreId")
        REFERENCES "Catalog"."Stores" ("Id") ON DELETE RESTRICT
);
